// רצף בין מחזורי מעקב (26.10.26): המשקל ההתחלתי נלקח מהמחזור הראשון ומספר השבוע ממשיך, כדי שמתאמן/ת במחזור שני לא "יתחיל/תתחיל מאפס"
function cycleFirst_(name) { try { const c = onbState(name).cycles || []; for (let k = 0; k < c.length; k++) if (c[k].first != null && c[k].first !== '') return Number(c[k].first); } catch (e) {} return null; }
function cycleWeeks_(name) { try { const pd = s => { const m = String(s || '').match(/(\d+)\/(\d+)\/(\d{4})/); return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null; }; return (onbState(name).cycles || []).reduce((a, x) => { const f = pd(x.from), t = pd(x.to); return a + (f && t ? Math.max(1, Math.round((t - f) / 864e5 / 7)) : 0); }, 0); } catch (e) { return 0; } }
